#!/usr/bin/env bash
# Regenerates ../branding.yaml (ConfigMap developer-hub-branding) from the
# source assets in ../branding/. Values are data URIs injected as env vars and
# referenced from app-config.yaml as ${BOX1_ICON_LOGO} (home banner only;
# the sidebar keeps the stock Red Hat Developer Hub logo for demos).
set -euo pipefail
cd "$(dirname "$0")/.."
mark="data:image/png;base64,$(base64 < branding/box1-mark-180.png | tr -d '\n')"
cat > branding.yaml <<YAML
# Generated by scripts/render-branding.sh; edit branding/ and re-run.
apiVersion: v1
kind: ConfigMap
metadata:
  name: developer-hub-branding
  namespace: rhdh
data:
  BOX1_ICON_LOGO: "${mark}"
YAML
